//! Synthetic arithmetic and source-event fixtures, not observed market data.
//! Frozen source vectors: bcf0b8f4965a644a3fd617937fbcb258160a369eac76363268b22a459a8be798.
//! Frozen event-account oracle: fc2146df45b55f15f8a1da20f9a8bfb1c70821384e74bd27d171f53c5d39e508.
//! Source reviewer had no Rust/reference exposure; account reviewer disclosed legacy-code exposure.
use super::*;
fn rows(values:&[(f64,f64,f64,f64)])->Vec<Row> {
    values.iter().enumerate().map(|(i,&(o,h,l,c))|Row{ticker:"SYNTHETIC".into(),date:format!("2020-{:02}-{:02}",i/28+1,i%28+1),open:o,high:h,low:l,close:c,volume:None}).collect()
}
fn near(actual:f64,expected:f64,label:&str) {
    assert!((actual.is_nan()&&expected.is_nan()) || (actual-expected).abs()<=1e-12*expected.abs().max(1.),"{label}: actual={actual:?}, expected={expected:?}");
}
fn source_case(id:&str,values:&[(f64,f64,f64,f64)],expected:&[(f64,usize,f64,usize,f64,bool,usize)]) {
    let r=rows(values);let ctx=Ctx::new(&r,&r,&[]);
    let run=backtest_costs(&ctx,id,0,r.len()-1,accounting::Costs::default(),&Params::new()).unwrap();
    assert_eq!(run.trades.len(),expected.len());
    for (t,&(dir,entry,px,exit,out,open,signal)) in run.trades.iter().zip(expected) {
        assert_eq!(t.dir,dir);assert_eq!(t.legs.len(),1);assert_eq!(t.legs[0].i,entry);near(t.legs[0].px,px,"entry open");
        assert_eq!(t.exit_i,exit);near(t.exit_px,out,"exit open/terminal close");assert_eq!(t.open,open);assert_eq!(t.signal_i,signal);
        assert_eq!(t.entry_kind,"open");assert!(t.legs[0].i>0);assert!(t.exits.is_empty());
    }
}

